				'lead' => $copy( 'Venix Concierge offers a professional chauffeur service in Warsaw: chauffeur hire and car hire with a driver, arranged around your schedule, alongside airport transfers, event transportation and delegation transfers. Concierge assistance and weddings are also available.', 'Venix Concierge oferuje wynajem samochodu z kierowcą w Warszawie — z profesjonalnym szoferem i pojazdem klasy premium, dopasowanymi do Państwa harmonogramu. Zajmujemy się też transferami lotniskowymi, transportem na wydarzenia i dla delegacji; dostępne są również usługi concierge i transport ślubny.', 'В Venix Concierge доступна аренда автомобиля с водителем в Варшаве: услуги персонального водителя и автомобиль Mercedes-Benz премиум-класса под Ваш график. Также мы организуем трансферы из аэропорта, транспорт для мероприятий и делегаций; доступны консьерж-сервис и свадебный транспорт.', 'تقدم Venix Concierge خدمة سائق خاص احترافية في وارسو، تشمل تأجير سيارة مع سائق بحسب جدولك، إلى جانب النقل من المطار وإليه ونقل الفعاليات ونقل الوفود. كما تتوفر مساعدة الكونسيرج وخدمات حفلات الزفاف.' ) ),
		'anchors' => array( 'chauffeur' => $copy( 'Chauffeur', 'Szofer', 'Водитель', 'السائق' ), 'airport' => $copy( 'Airport', 'Lotnisko', 'Аэропорт', 'المطار' ), 'events' => $copy( 'Events', 'Wydarzenia', 'Мероприятия', 'الفعاليات' ), 'delegations' => $copy( 'Delegations', 'Delegacje', 'Делегации', 'الوفود' ), 'protection' => $copy( 'Protection', 'Ochrona', 'Охрана', 'الحماية' ), 'flights' => $copy( 'Private Flights', 'Loty prywatne', 'Частные перелёты', 'الطيران الخاص' ), 'embassy' => $copy( 'Embassy', 'Ambasady', 'Посольства', 'السفارات' ), 'concierge' => $copy( 'Concierge', 'Concierge', 'Консьерж', 'الكونسيرج' ), 'weddings' => $copy( 'Weddings', 'Śluby', 'Свадьбы', 'حفلات الزفاف' ) ),
